#include <stdio.h>
int main() {
    int a, b;
    printf("দুইটি সংখ্যা দিন: ");
    scanf("%d %d", &a, &b);

    printf("যোগফল = %d\n", a + b);
    printf("বিয়োগফল = %d\n", a - b);
    printf("গুণফল = %d\n", a * b);

    if (b != 0) // শূন্য দিয়ে ভাগ করা যায় না
        printf("ভাগফল = %.2f\n", (float)a / b);
