int main() {
    int n, isPrime = 1;
    printf("সংখ্যা দিন: ");
    scanf("%d", &n);
    if (n <= 1) isPrime = 0;
    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) { isPrime = 0; break; }
    }
    printf("%d %s\n", n, isPrime ? "মৌলিক সংখ্যা (Prime)" : "মৌলিক সংখ্যা নয়");
    return 0;
}

#include <stdio.h>
int isPrime(int n) {
    if (n <= 1) return 0;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return 0;
    return 1;
}
int main() {
    int low, high;
    printf("শুরু ও শেষ দিন: ");
    scanf("%d %d", &low, &high);
    printf("মৌলিক সংখ্যাসমূহ: ");
    for (int i = low; i <= high; i++)
        if (isPrime(i)) printf("%d ", i);
    printf("\n");
    return 0;
}

