#include <stdio.h>
int main() {
    int a, b, x, y, temp, gcd, lcm;
    printf("দুইটি সংখ্যা দিন: ");
    scanf("%d %d", &a, &b);
    x = a; y = b;
    while (y != 0) { // ইউক্লিডের অ্যালগরিদম
        temp = y;
        y = x % y;
        x = temp;
    }
    gcd = x;
    lcm = (a * b) / gcd;
    printf("GCD = %d\n", gcd);
    printf("LCM = %d\n", lcm);
    return 0;
}

