#include <stdio.h>
int main() {
    char s1[] = "abc", s2[] = "abd";
    int i = 0, isEqual = 1;
    while (s1[i] != '\0' && s2[i] != '\0') {
        if (s1[i] != s2[i]) { isEqual = 0; break; }
