#include <stdio.h>
long long fact(int n) {
    if (n <= 1) return 1; // বেস কেস
    return n * fact(n - 1); // রিকার্সিভ কল
}
int main() {
    int n = 5;
    printf("%d! = %lld\n", n, fact(n));
