#include <stdio.h>
#define MAX 5
int stack[MAX], top = -1;

void push(int val) {
    if (top == MAX - 1) { printf("Stack Overflow\n"); return; }
    stack[++top] = val;
}
int pop() {
    if (top == -1) { printf("Stack Underflow\n"); return -1; }
    return stack[top--];
}
int main() {
    push(10); push(20); push(30);
    printf("Pop: %d\n", pop());
    printf("Pop: %d\n", pop());
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
struct Node {
    int data;
    struct Node *next;
};
struct Node *top = NULL;

void push(int val) {
    struct Node *newNode = (struct Node*) malloc(sizeof(struct Node));
    newNode->data = val;
    newNode->next = top; // নতুন নোড আগেরটার আগে বসবে
    top = newNode;
}
int pop() {
    if (top == NULL) { printf("Stack Empty\n"); return -1; }
    int val = top->data;
    struct Node *temp = top;
    top = top->next;
    free(temp);
    return val;
}
int main() {
    push(10); push(20); push(30);
    printf("Pop: %d\n", pop());
    printf("Pop: %d\n", pop());
    return 0;
}

#include <stdio.h>
#define MAX 5
int queue[MAX], front = -1, rear = -1;

void enqueue(int val) {
    if (rear == MAX - 1) { printf("Queue Full\n"); return; }
    if (front == -1) front = 0;
    queue[++rear] = val;
}
int dequeue() {
    if (front == -1 || front > rear) { printf("Queue Empty\n"); return -1; }
    return queue[front++];
}
int main() {
    enqueue(10); enqueue(20); enqueue(30);
    printf("Dequeue: %d\n", dequeue());
    printf("Dequeue: %d\n", dequeue());
    return 0;
}

#include <stdio.h>
#define MAX 5
int cqueue[MAX], front = -1, rear = -1;

void enqueue(int val) {
    if ((rear + 1) % MAX == front) { printf("Queue Full\n"); return; }
    if (front == -1) front = 0;
    rear = (rear + 1) % MAX;
    cqueue[rear] = val;
}
int dequeue() {
    if (front == -1) { printf("Queue Empty\n"); return -1; }
    int val = cqueue[front];
    if (front == rear) front = rear = -1; // শেষ এলিমেন্ট
    else front = (front + 1) % MAX;
    return val;
}
int main() {
    enqueue(1); enqueue(2); enqueue(3);
    printf("Dequeue: %d\n", dequeue());
    enqueue(4);
    printf("Dequeue: %d\n", dequeue());
    return 0;
}

