#include <stdio.h>
#include <string.h>
void sortStr(char *str) {
    int n = strlen(str);
    for (int i = 0; i < n-1; i++)
        for (int j = 0; j < n-i-1; j++)
            if (str[j] > str[j+1]) {
                char t = str[j]; str[j] = str[j+1]; str[j+1] = t;
            }
}
int main() {
    char s1[] = "listen", s2[] = "silent";
    char a[50], b[50];
    strcpy(a, s1); strcpy(b, s2);
    sortStr(a); sortStr(b);
    if (strcmp(a, b) == 0)
        printf("অ্যানাগ্রাম (Anagram)\n");
    else
        printf("অ্যানাগ্রাম নয়\n");
    return 0;
}

