#include <stdio.h>
struct Student {
    char name[50];
    int marks[3];
    float average;
    char grade;
};
int main() {
    struct Student s;
    printf("নাম দিন: ");
    scanf("%s", s.name);
    int total = 0;
    for (int i = 0; i < 3; i++) {
        printf("বিষয় %d এর নম্বর: ", i + 1);
        scanf("%d", &s.marks[i]);
        total += s.marks[i];
    }
    s.average = total / 3.0;
    if (s.average >= 80) s.grade = 'A';
    else if (s.average >= 60) s.grade = 'B';
    else if (s.average >= 40) s.grade = 'C';
    else s.grade = 'F';

    printf("\nনাম: %s, গড়: %.2f, গ্রেড: %c\n", s.name, s.average, s.grade);
    return 0;
}

#include <stdio.h>
#include <string.h>
struct Book {
    int id;
    char title[50];
    int isIssued; // 0 = আছে, 1 = ইস্যু হয়েছে
};
int main() {
    struct Book books[10];
    int count = 0, choice;
    do {
        printf("\n১.বই যোগ ২.বই দেখুন ৩.বই ইস্যু ৪.প্রস্থান\nপছন্দ: ");
