    b = a - b; // b = আসল a
    a = a - b; // a = আসল b
    cout << "ছাড়া (যোগ-বিয়োগ): a=" << a << ", b=" << b << endl;

    // ---- XOR পদ্ধতি ----
    a = 5; b = 10;
    a = a ^ b;
    b = a ^ b;
    a = a ^ b;
    cout << "XOR পদ্ধতি: a=" << a << ", b=" << b << endl;
