#include <iostream>
using namespace std;
bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}
int main() {
    int low, high;
    cout << "শুরু ও শেষ দিন: ";
    cin >> low >> high;
    cout << "মৌলিক সংখ্যাসমূহ: ";
    for (int i = low; i <= high; i++)
        if (isPrime(i)) cout << i << " ";
    cout << endl;
    return 0;
}

