#include <iostream>
using namespace std;
#define MAX 5
int stackArr[MAX], top = -1;

void push(int val) {
    if (top == MAX - 1) { cout << "Stack Overflow" << endl; return; }
    stackArr[++top] = val;
}
int pop() {
    if (top == -1) { cout << "Stack Underflow" << endl; return -1; }
    return stackArr[top--];
}
int main() {
    push(10); push(20); push(30);
    cout << "Pop: " << pop() << endl;
    cout << "Pop: " << pop() << endl;
    return 0;
}

#include <iostream>
using namespace std;
struct Node {
    int data;
    Node *next;
};
Node *top = nullptr;

void push(int val) {
    Node *newNode = new Node();
    newNode->data = val;
    newNode->next = top; // নতুন নোড আগেরটার আগে বসবে
    top = newNode;
}
int pop() {
    if (top == nullptr) { cout << "Stack Empty" << endl; return -1; }
    int val = top->data;
    Node *temp = top;
    top = top->next;
    delete temp;
    return val;
}
int main() {
    push(10); push(20); push(30);
    cout << "Pop: " << pop() << endl;
    cout << "Pop: " << pop() << endl;
    return 0;
}

#include <iostream>
using namespace std;
#define MAX 5
int queueArr[MAX], front = -1, rear = -1;

void enqueue(int val) {
    if (rear == MAX - 1) { cout << "Queue Full" << endl; return; }
    if (front == -1) front = 0;
    queueArr[++rear] = val;
}
int dequeue() {
    if (front == -1 || front > rear) { cout << "Queue Empty" << endl; return -1; }
    return queueArr[front++];
}
int main() {
    enqueue(10); enqueue(20); enqueue(30);
    cout << "Dequeue: " << dequeue() << endl;
    cout << "Dequeue: " << dequeue() << endl;
